<template>
  <v-dialog
    :value="value"
    max-width="560"
    persistent
    scrollable
    @input="$emit('input', $event)"
  >
    <v-card v-if="leave">
      <v-card-title class="recall-title">
        <v-icon left color="amber darken-3">mdi-account-arrow-left</v-icon>
        Recall from leave
        <v-spacer></v-spacer>
        <v-btn icon :disabled="submitting" @click="close">
          <v-icon>mdi-close</v-icon>
        </v-btn>
      </v-card-title>
      <v-divider></v-divider>

      <v-card-text class="pa-5">
        <!-- Leave summary -->
        <div class="leave-summary mb-5">
          <div class="leave-summary__name">{{ leave.staffName }}</div>
          <div class="leave-summary__meta">
            {{ leave.categoryName }} · {{ formatDate(leave.startDate) }} –
            {{ formatDate(leave.endDate) }} · {{ leave.days }}
            {{ leave.days === 1 ? "day" : "days" }}
          </div>
        </div>

        <template v-if="!confirming">
          <v-form ref="form" v-model="valid" @submit.prevent="toConfirm">
            <v-menu
              v-model="dateMenu"
              :close-on-content-click="false"
              transition="scale-transition"
              offset-y
              min-width="auto"
            >
              <template v-slot:activator="{ on, attrs }">
                <v-text-field
                  id="recall-date"
                  :value="formatDate(recallDate) === 'N/A' ? '' : formatDate(recallDate)"
                  label="Report back on"
                  hint="The first day the staff member must be back at work"
                  persistent-hint
                  prepend-inner-icon="mdi-calendar"
                  readonly
                  outlined
                  :rules="[(v) => !!v || 'Choose the day they must report back']"
                  v-bind="attrs"
                  v-on="on"
                ></v-text-field>
              </template>
              <v-date-picker
                v-model="recallDate"
                :min="minDate"
                :max="maxDate"
                no-title
                @input="dateMenu = false"
              ></v-date-picker>
            </v-menu>

            <v-textarea
              id="recall-reason"
              v-model.trim="recallReason"
              class="mt-4"
              label="Reason for recall (required)"
              outlined
              auto-grow
              rows="3"
              :hint="reasonHint"
              persistent-hint
              :rules="[
                (v) => !!v || 'Give a reason for the recall',
                (v) => (v && v.length >= 10) || 'Use at least 10 characters',
              ]"
            ></v-textarea>
          </v-form>

          <!-- Days preview -->
          <div v-if="recallDate" class="days-preview">
            <div class="days-preview__item">
              <div class="days-preview__label">Days taken</div>
              <div class="days-preview__value">
                <v-progress-circular
                  v-if="loadingDays"
                  indeterminate
                  size="18"
                  width="2"
                ></v-progress-circular>
                <template v-else>{{ daysTakenLabel }}</template>
              </div>
            </div>
            <div class="days-preview__item">
              <div class="days-preview__label">Returned to balance</div>
              <div class="days-preview__value days-preview__value--return">
                <v-progress-circular
                  v-if="loadingDays"
                  indeterminate
                  size="18"
                  width="2"
                ></v-progress-circular>
                <template v-else>{{ daysReturnedLabel }}</template>
              </div>
            </div>
          </div>
          <div v-if="daysError" class="field-note field-note--error mt-2">
            {{ daysError }}
          </div>
        </template>

        <!-- Confirmation step -->
        <div v-else class="confirm-box">
          <div class="confirm-box__title">
            Recall {{ leave.staffName }} to report back on
            {{ formatDate(recallDate) }}?
          </div>
          <ul class="confirm-box__list">
            <li>The leave ends early and is marked <strong>Recalled</strong>.</li>
            <li v-if="daysReturned !== null">
              {{ daysReturned }} {{ daysReturned === 1 ? "day goes" : "days go" }}
              back to their annual leave balance.
            </li>
            <li>The staff member, their HOD and HR are notified.</li>
          </ul>
          <div class="confirm-box__reason">{{ recallReason }}</div>
        </div>

        <v-alert
          v-if="submitError"
          type="error"
          dense
          text
          class="mt-4 mb-0"
        >
          {{ submitError }}
        </v-alert>
      </v-card-text>

      <v-divider></v-divider>
      <v-card-actions class="px-5 py-3">
        <template v-if="!confirming">
          <span v-if="missing.length" class="missing-note" :class="{ 'missing-note--alert': showMissing }">
            <v-icon x-small :color="showMissing ? 'error' : 'blue-grey'" class="mr-1">mdi-information-outline</v-icon>
            Add {{ missing.join(" and ") }} to recall.
          </span>
          <v-spacer></v-spacer>
          <v-btn text :disabled="submitting" @click="close">Cancel</v-btn>
          <!-- stays visible but faded until a date and reason are given; clicking it then points at what's missing -->
          <v-btn
            color="amber darken-3"
            dark
            depressed
            :class="{ 'btn-faint': !canContinue }"
            :aria-disabled="!canContinue ? 'true' : 'false'"
            @click="onRecallClick"
          >
            <v-icon left small>mdi-account-arrow-left</v-icon>
            Recall
          </v-btn>
        </template>
        <template v-else>
          <v-btn text :disabled="submitting" @click="confirming = false">
            <v-icon left>mdi-arrow-left</v-icon>
            Back
          </v-btn>
          <v-spacer></v-spacer>
          <v-btn
            color="amber darken-3"
            dark
            depressed
            :loading="submitting"
            @click="submit"
          >
            Confirm recall
          </v-btn>
        </template>
      </v-card-actions>
    </v-card>
  </v-dialog>
</template>

<script>
const RECALL_QUESTIONNAIRE = "http://ihris.org/fhir/Questionnaire/leave-recall";

const toISO = (date) => {
  const pad = (n) => String(n).padStart(2, "0");
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
};

const parseDate = (value) => {
  if (!value) return null;
  const [year, month, day] = String(value).split("T")[0].split("-").map(Number);
  if (!year) return null;
  return new Date(year, (month || 1) - 1, day || 1);
};

const addDays = (value, days) => {
  const date = parseDate(value);
  if (!date) return "";
  date.setDate(date.getDate() + days);
  return toISO(date);
};

export default {
  name: "LeaveRecall",
  props: {
    // v-model: dialog open/closed
    value: { type: Boolean, default: false },
    // { id, practitionerId, staffName, categoryName, startDate, endDate, days }
    leave: { type: Object, default: null },
  },

  data() {
    return {
      valid: false,
      dateMenu: false,
      recallDate: "",
      recallReason: "",
      confirming: false,
      showMissing: false,
      submitting: false,
      submitError: "",
      loadingDays: false,
      daysTaken: null,
      daysError: "",
    };
  },

  computed: {
    // A recall date must be today or later, after the first day of leave, and no later than the last day
    minDate() {
      if (!this.leave) return "";
      const today = toISO(new Date());
      const dayAfterStart = addDays(this.leave.startDate, 1);
      return today > dayAfterStart ? today : dayAfterStart;
    },
    maxDate() {
      return this.leave ? this.leave.endDate : "";
    },
    daysReturned() {
      if (this.daysTaken === null || !this.leave) return null;
      return Math.max(0, (Number(this.leave.days) || 0) - this.daysTaken);
    },
    daysTakenLabel() {
      return this.daysTaken === null ? "–" : this.dayCount(this.daysTaken);
    },
    daysReturnedLabel() {
      return this.daysReturned === null ? "–" : this.dayCount(this.daysReturned);
    },
    // what still stops the recall, in plain words
    missing() {
      const missing = [];
      if (!this.recallDate) missing.push("a report-back date");
      if (this.recallReason.length < 10) missing.push("a reason");
      return missing;
    },
    reasonHint() {
      const remaining = 10 - this.recallReason.length;
      if (remaining > 0) {
        return this.recallReason.length
          ? `${remaining} more character${remaining === 1 ? "" : "s"} needed`
          : "Explain why they need to come back (at least 10 characters)";
      }
      return "";
    },
    canContinue() {
      return (
        this.valid &&
        !!this.recallDate &&
        this.recallReason.length >= 10 &&
        !this.loadingDays &&
        !this.submitting
      );
    },
  },

  watch: {
    value(open) {
      if (open) this.reset();
    },
    recallDate() {
      this.loadDaysTaken();
    },
  },

  methods: {
    reset() {
      this.recallDate = "";
      this.recallReason = "";
      this.confirming = false;
      this.showMissing = false;
      this.submitting = false;
      this.submitError = "";
      this.daysTaken = null;
      this.daysError = "";
      if (this.$refs.form) this.$refs.form.resetValidation();
    },

    close() {
      if (this.submitting) return;
      this.$emit("input", false);
    },

    dayCount(n) {
      return `${n} ${n === 1 ? "day" : "days"}`;
    },

    // Days taken = working days from the start up to the day before they report back,
    // counted by the same server rule (weekends and public holidays excluded) used for leave requests
    async loadDaysTaken() {
      this.daysTaken = null;
      this.daysError = "";
      if (!this.recallDate || !this.leave) return;
      const lastDayOnLeave = addDays(this.recallDate, -1);
      if (lastDayOnLeave < this.leave.startDate) {
        this.daysTaken = 0;
        return;
      }
      const requested = this.recallDate;
      this.loadingDays = true;
      try {
        const response = await fetch(
          `/site/leave/leaveDays?startDate=${this.leave.startDate}&endDate=${lastDayOnLeave}`,
        );
        if (!response.ok) throw new Error("Could not count the days taken");
        const data = await response.json();
        if (requested === this.recallDate) this.daysTaken = Number(data.days) || 0;
      } catch (error) {
        console.error(error);
        this.daysError =
          "Couldn't work out the days taken. You can still recall; the server will calculate them.";
      } finally {
        this.loadingDays = false;
      }
    },

    onRecallClick() {
      if (!this.canContinue) {
        // show the field errors and highlight the note instead of doing nothing
        this.showMissing = true;
        if (this.$refs.form) this.$refs.form.validate();
        return;
      }
      this.toConfirm();
    },

    toConfirm() {
      if (!this.$refs.form || !this.$refs.form.validate() || !this.canContinue) return;
      this.submitError = "";
      this.confirming = true;
    },

    async submit() {
      this.submitting = true;
      this.submitError = "";
      try {
        const response = await fetch(
          // editing=false is required: the QuestionnaireResponse route JSON-parses it on every request
          `/fhir/QuestionnaireResponse?practitioner=${encodeURIComponent(this.leave.practitionerId)}&editing=false`,
          {
            method: "POST",
            headers: { "Content-Type": "application/fhir+json" },
            body: JSON.stringify({
              resourceType: "QuestionnaireResponse",
              questionnaire: RECALL_QUESTIONNAIRE,
              status: "completed",
              item: [],
              requestId: this.leave.id,
              recallDate: this.recallDate,
              recallReason: this.recallReason,
            }),
          },
        );
        if (!response.ok) {
          throw new Error(await this.readError(response));
        }
        this.$emit("recalled", { leaveId: this.leave.id, recallDate: this.recallDate });
        this.$emit("input", false);
      } catch (error) {
        console.error("Error recalling staff member:", error);
        this.submitError = error.message || "The recall could not be saved. Try again.";
      } finally {
        this.submitting = false;
      }
    },

    // Workflow errors come back as { message }, { err } or an OperationOutcome
    async readError(response) {
      try {
        const body = await response.json();
        return (
          body?.message ||
          body?.err ||
          body?.issue?.[0]?.diagnostics ||
          `The recall could not be saved (error ${response.status}).`
        );
      } catch (e) {
        return `The recall could not be saved (error ${response.status}).`;
      }
    },

    formatDate(value) {
      const date = parseDate(value);
      if (!date) return "N/A";
      return date.toLocaleDateString("en-GB", {
        day: "numeric",
        month: "short",
        year: "numeric",
      });
    },
  },
};
</script>

